const offers = .map(i => i.json);

// Ordenar por effective_price
offers.sort((a, b) => (a.price.currentCents + (a.shipping.amountCents || 0)) - (b.price.currentCents + (b.shipping.amountCents || 0)));

const winner = offers[0];
const alternatives = offers.slice(1, 4);

 = { winner, alternatives };
